460	static void cc1352_bootloader_send_nack(struct gb_beagleplay *bg)
461	{
462		static const u8 nack[] = { 0x00, CC1352_BOOTLOADER_NACK };
463	
464		serdev_device_write_buf(bg->sd, nack, sizeof(nack));
465	}
